@startuml

class Person {}

class Student extends Person {
  + name : string
  + email : string
}

class Tutor extends Person {
  + name : string
  + email : string
  + bankAccount : string
}

class Subject {
  + name : string
}

class TutoringOffer {
  + expertiseLevel : string
  + hourlyPrice : float
}

class Availability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + requestedLevel : string
  + targetDateTime : datetime
}

class TutoringSession {
  + dateTime : datetime
  + status : string
  + pricePaid : float
}

class Payment {
  + method : string
}

class Award {
  + month : string
}

Tutor "1" -- "*" TutoringOffer
Tutor "1" -- "*" Availability
Tutor "1" -- "*" TutoringOffer : offers
Subject "1" -- "*" TutoringOffer
Student "1" -- "*" TutoringRequest
Tutor "1" -- "*" TutoringRequest : receives
TutoringRequest "1" -- "0..1" TutoringSession : becomes
Student "1" -- "*" TutoringSession
Tutor "1" -- "*" TutoringSession
TutoringSession "1" -- "0..1" Payment : paid via
Subject "1" -- "*" Award : awarded in
Tutor "0..1" -- "*" Award : receives

@enduml

